#include <stdio.h>
#include <string.h>

#define MAX_ARGS 64      // maximum number of strings (excluding program name)
#define MAX_LEN 1024      // maximum allowed length of each string

int main(int argc, char *argv[])
{
    // Too many arguments (more than 64 strings, i.e., argc > 65)
    if (argc > MAX_ARGS + 1) {
        puts("TOO_MANY");
        return 0;
    }
    // No strings supplied
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    // Check length of the first string and use it as reference
    const char *ref = argv[1];
    size_t ref_len = strlen(ref);
    if (ref_len > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    size_t lcp_len = ref_len; // current longest common prefix length

    // Process remaining arguments
    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t len = strlen(s);
        if (len > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
        // Reduce lcp_len while characters differ
        size_t j = 0;
        while (j < lcp_len && ref[j] == s[j]) {
            ++j;
        }
        lcp_len = j;
        if (lcp_len == 0) {
            break; // no common prefix possible any more
        }
    }

    // Output the longest common prefix followed by a newline
    for (size_t k = 0; k < lcp_len; ++k) {
        putchar(ref[k]);
    }
    putchar('\n');
    return 0;
}
